parameters.jsCode:
// Turn the AI's commercial product names into buyer-intent web
// queries, one Serper call each.
const body = $('Webhook').first().json.body || $('Webhook').first().json;
const code = String(body.hs_code || '').replace(/\D/g, '');
if (code.length !== 6) {
  throw new Error(`LeadPilot Error: invalid_hs_code - expected a 6-digit HS code, got "${body.hs_code}".`);
}

// Parse the AI's terms; fall back to what the user typed, then to
// the official description, so a bad AI reply degrades instead of
// failing the run.
let terms = [];
try {
  const parsed = JSON.parse($json.choices[0].message.content);
  terms = Array.isArray(parsed.terms) ? parsed.terms : [];
} catch (e) {
  terms = [];
}

const clean = t => String(t || '')
  .replace(/\b(n\.e\.s\.|nes|other|parts thereof)\b/gi, ' ')
  .replace(/["'()\[\],;:]+/g, ' ')
  .replace(/\d{4,}/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

terms = [...new Set(terms.map(clean).filter(t => t.length > 2))].slice(0, 3);

if (!terms.length) {
  const fallback = clean(body.product_term) || clean(body.hs_description);
  if (!fallback) {
    throw new Error(`LeadPilot Error: no_product_terms - HS ${code} could not be translated into searchable product names, and no description was supplied to fall back on.`);
  }
  terms = [fallback];
}

// Company-type -> OR-group of trade words buyers of that type use.
// Keep in step with LeadPilot_Backend/app/services/company_types.py
// and LeadPilot.json's own serper node.
const typeTerms = {
  distributor: ['distributor', 'wholesaler', 'importer', 'trading company', 'stockist'],
  brand_oem: ['OEM', 'ODM', 'custom manufacturer', 'private label', 'contract manufacturer'],
  retailer: ['retailer', 'store', 'shop', 'dropshipping', 'reseller'],
  installer: ['installer', 'contractor', 'system integrator', 'commissioning', 'maintenance'],
};

// No company type picked: cast the general buyer net instead, so
// the query still favours trade sites over spec sheets and news.
const words = typeTerms[body.company_type] || ['importer', 'distributor', 'wholesaler', 'supplier'];
const group = `(${words.map(w => `"${w}"`).join(' OR ')})`;
const site = body.country_tld ? ` site:.${body.country_tld}` : '';

// Serper caps `num` at 10 on a free account -- anything higher is
// refused with a misleading "Query pattern not allowed for free
// accounts" 400. One page per term; "Extract Domains" merges and
// de-duplicates across all of them.
return terms.map(term => ({
  json: {
    hs_code: code,
    product: term,
    // Every term this run searched, for the results payload.
    product_terms: terms,
    query: `${term} ${group}${site}`,
    page: 1,
    // SerpApi gl code for Serper's own country bias, on top of the
    // site: restriction. Null (worldwide) lets Serper pick.
    gl: body.country || undefined,
  },
}));

