// Same blacklist LeadPilot.json's B2B search uses. Directories and
// marketplaces are exactly what a bare HS-code dork tends to surface,
// so this list matters more here than for a keyword search.
const blacklist = [
  'linkedin.com', 'facebook.com', 'youtube.com', 'instagram.com', 'twitter.com', 'tiktok.com', 'x.com', 'pinterest.com',
  'alibaba.com', 'amazon.com', 'made-in-china.com', 'globalsources.com', 'thomasnet.com',
  'yellowpages.com', 'yelp.com', 'trustpilot.com', 'crunchbase.com', 'bloomberg.com',
  'wikipedia.org', 'reddit.com', 'quora.com', 'medium.com', 'tradeimex.in', 'seair.co.in',
  'worldbank.org', 'zippia.com', 'unicargo.com', 'ebay.com', 'walmart.com',
  // HS-code lookup / tariff reference sites: they list every code
  // and are never a buyer.
  'hts.usitc.gov', 'trade.gov', 'customs.gov', 'tariffnumber.com', 'hscode.org', 'findhs.codes', 'zauba.com', 'volza.com', 'importgenius.com', 'panjiva.com', 'exportgenius.in', 'cybex.in', 'infodriveindia.com', 'wto.org', 'europa.eu'
];
const forbiddenTLDs = ['.gov', '.edu'];

// Carried onto every row so the AI pass and the results payload
// keep the product context. Read from "Build Product Queries" rather
// than the Serper response, which only holds search output.
const first = $('Build Product Queries').first().json;
const hs_code = first.hs_code;
const product = first.product;

const seen = new Set();
const output = [];
for (const item of $input.all()) {
  for (const result of (item.json.organic || [])) {
    if (!result.link) continue;
    const url = result.link.toLowerCase();
    if (blacklist.some(d => url.includes(d))) continue;
    if (forbiddenTLDs.some(t => url.includes(t))) continue;

    let domain = result.link;
    try {
      domain = new URL(result.link).hostname.replace(/^www\./, '').toLowerCase();
    } catch (e) {
      domain = domain.replace(/^(?:https?:\/\/)?(?:www\.)?([^\/]+).*/i, '$1').toLowerCase();
    }
    if (!domain || seen.has(domain)) continue;
    seen.add(domain);

    output.push({ json: { hs_code, product, url: result.link, title: result.title, snippet: result.snippet, domain } });
  }
}

if (!output.length) {
  // Tell the two cases apart. If Serper itself errored (On Error
  // keeps the error item alive so the run is not lost), saying
  // "no companies for this HS code" would send the user off
  // rewording a perfectly good search.
  const failed = $input.all().find(i => i.json && i.json.error);
  if (failed) {
    const detail = failed.json.error.message || JSON.stringify(failed.json.error);
    throw new Error(`LeadPilot Error: search_provider_error - the web search provider rejected the request: ${detail}`);
  }
  throw new Error('LeadPilot Error: no_companies_found - the web search returned no usable company websites for this HS code.');
}
return output;

