parameters.jsCode:
// Pair each verdict back with the domain it was asked about --
// DeepSeek replies in input order, so index alignment against
// "Extract Domains" is what restores url/title/snippet/domain.
// A reply we cannot parse scores 0 and is dropped by the Filter
// below rather than passed through unjudged.
const origin = $('Extract Domains').all();
const output = [];

$input.all().forEach((item, i) => {
  const orig = origin[i]?.json || {};
  let score = 0;
  let isCompany = false;
  try {
    const parsed = JSON.parse(item.json.choices[0].message.content);
    score = parsed.score || 0;
    isCompany = Boolean(parsed.is_company);
  } catch (e) {
    score = 0;
    isCompany = false;
  }

  output.push({
    json: {
      hs_code: orig.hs_code,
      url: orig.url,
      title: orig.title,
      snippet: orig.snippet,
      domain: orig.domain,
      ai_score: score,
      is_company: isCompany,
    },
  });
});

return output;

// Keep only what the AI judged a real company, scoring 5+. This is
// the step that stops tariff/customs/data-portal domains reaching
// Snov.io, which rejects them with a 422.
const kept = $input.all().filter(i =>
  i.json && i.json.is_company === true && (i.json.ai_score || 0) >= 5);

if (!kept.length) {
  throw new Error(`LeadPilot Error: no_companies_found - the web search found ${$input.all().length} results for this HS code, but none were real company websites (they were tariff lookups, customs data portals or directories).`);
}
return kept;

// 1. Retrieve target min/max boundaries from Webhook payload
const webhookData = $('Webhook').first().json;
const body = webhookData.body || webhookData;

const targetMin = body.company_size_min !== undefined && body.company_size_min !== null ? parseInt(body.company_size_min, 10) : null;
const targetMax = body.company_size_max !== undefined && body.company_size_max !== null ? parseInt(body.company_size_max, 10) : null;

// Set your hard limit here to control costs
const MAX_COMPANIES = 30;

// Helper function to parse size strings like "11-50", "1-10", "501+", "11 - 50"
function parseSizeRange(sizeStr) {
  if (!sizeStr || typeof sizeStr !== 'string') return null;

  const numbers = sizeStr.match(/\d+/g);
  if (!numbers || numbers.length === 0) return null;

  if (numbers.length === 1) {
    const val = parseInt(numbers[0], 10);
    return { min: val, max: val };
  }

  return {
    min: parseInt(numbers[0], 10),
    max: parseInt(numbers[1], 10)
  };
}

const keptItems = [];

for (const item of $input.all()) {
  // A Snov.io call that failed (On Error continues with the error item) has
  // no meta.domain and must not reach "Start prospect profiles".
  if (!item.json || !item.json.meta || !item.json.meta.domain) continue;

  const companyData = item.json.data || item.json;
  const companySizeStr = companyData.size || item.json.size;

  // RULE 1: If user selected "any size" (targets are null), allow ALL companies immediately
  if (targetMin === null && targetMax === null) {
    keptItems.push(item);
    continue;
  }

  // RULE 2: Unknown size is not evidence of a bad fit -- Snov.io simply has no
  // data for this company. Keep it rather than lose a possible hidden gem;
  // only a confidently-parsed size can disqualify a company below.
  if (!companySizeStr || companySizeStr.trim() === "" || companySizeStr.toLowerCase() === "n/a") {
    keptItems.push(item);
    continue;
  }

  // Parse actual company size range
  const actualRange = parseSizeRange(companySizeStr);

  // If size string could not be parsed into numbers, we are not confident it's
  // out of range either -- keep it rather than discard on an unreadable value.
  if (!actualRange) {
    keptItems.push(item);
    continue;
  }

  // Check strict range overlap. Only discard when Snov.io gave us a real,
  // parsed size range that confidently falls outside the target.
  const aboveMin = targetMin === null || actualRange.max >= targetMin;
  const belowMax = targetMax === null || actualRange.min <= targetMax;
  const isWithinRange = aboveMin && belowMax;

  if (isWithinRange) {
    keptItems.push(item);
  }
}

if (!keptItems.length) {
  // Two very different causes, and blaming the size filter for the other one
  // sends the user off widening a band that was never the problem. A domain
  // Snov.io refused (422 "We can not process this domain") arrives here as an
  // error item with no meta.domain, kept alive by On Error so one bad domain
  // does not lose the run.
  const all = $input.all();
  const rejected = all.filter(i => !i.json || !i.json.meta || !i.json.meta.domain).length;
  if (rejected === all.length) {
    throw new Error(`LeadPilot Error: no_companies_found - the data provider could not process any of the ${all.length} domains found for this HS code. They were most likely trade-data or tariff sites rather than real company websites.`);
  }
  throw new Error(`LeadPilot Error: no_company_size_match - ${all.length - rejected} companies were found but none matched the requested company size.`);
}
return keptItems.slice(0, MAX_COMPANIES);

// --- CONFIGURABLE LIMITS ---
const MAX_PER_COMPANY = 5;       // Hard limit per domain

// The user's Result Limit from the Advanced Filters panel. Default matches
// LeadPilot.json's own cap if it ever arrives missing.
const _body = $('Webhook').first().json.body || $('Webhook').first().json;
const MAX_TOTAL_PROSPECTS = Math.max(1, parseInt(_body.result_limit, 10) || 100);

// Snov.io's own 'positions' filter (see "Start prospect profiles") already did
// the real role filtering when the user picked a Target Title -- it was given
// the exact job titles from CONTACT_ROLES (app/services/search_targeting.py)
// and only returns matching prospects. This array is the safety net for the
// "all titles" case (no native filter applied, so every title comes through)
// and for stray junk titles (interns, generic "Info", etc.) slipping past that.
const validRoles = [
  // C-level / ownership
  "ceo", "cfo", "coo", "cmo", "cto", "chief", "owner", "founder", "co-founder",
  "president", "chairman", "chairwoman", "principal", "proprietor", "partner",
  // Management / leadership (any department)
  "director", "managing director", "general manager", "gm", "vp", "vice president",
  "head of", "head", "lead", "manager", "management", "executive", "supervisor",
  "administrator", "in charge",
  // Procurement / sourcing / supply chain
  "procurement", "purchasing", "purchase", "buyer", "buying", "sourcing",
  "supply chain", "category manager", "vendor manager", "import", "export",
  // Sales / business development / operations / engineering
  "sales", "business development", "commercial", "operations", "ops",
  "engineer", "engineering", "technical", "r&d",
  // Common non-English equivalents (DE/FR/ES/PT/IT) so translated titles survive
  "einkauf", "geschaeftsfuehrer", "geschäftsführer", "direttore", "responsabile",
  "achat", "directeur", "gerente", "director general", "diretor"
];

let totalKept = 0;
const finalItems = [];

for (const item of $input.all()) {
  if (totalKept >= MAX_TOTAL_PROSPECTS) break;

  let prospectsArray = Array.isArray(item.json.data) ? item.json.data :
                       Array.isArray(item.json.prospects) ? item.json.prospects : [];

  // Skip companies that have no prospect data
  if (!prospectsArray || prospectsArray.length === 0) {
    continue;
  }

  // RULE 1: Role filtering -- a wide net of decision-maker keywords.
  let qualifiedProspects = prospectsArray.filter(p => {
    const title = (p.position || p.title || p.job_title || "").toLowerCase();
    if (!title) return false;
    return validRoles.some(role => title.includes(role));
  });

  if (qualifiedProspects.length === 0) continue;

  // RULE 2: Hard Limit Per Company
  let slicedProspects = qualifiedProspects.slice(0, MAX_PER_COMPANY);

  // RULE 3: Total Output Limit check
  if (totalKept + slicedProspects.length > MAX_TOTAL_PROSPECTS) {
    const roomLeft = MAX_TOTAL_PROSPECTS - totalKept;
    slicedProspects = slicedProspects.slice(0, roomLeft);
  }

  totalKept += slicedProspects.length;

  const newItem = { json: { ...item.json } };
  newItem.json.data = slicedProspects;
  finalItems.push(newItem);
}

// IF ZERO PROSPECTS FOUND ACROSS ALL COMPANIES, THROW ERROR TO TRIGGER ERROR WORKFLOW
if (finalItems.length === 0 || totalKept === 0) {
  throw new Error("LeadPilot Error: Zero decision-makers found matching target roles for any analyzed companies.");
}

return finalItems;

// The verifier answers { data: [ { email, result } ] }, but everything
// after Merge expects the prospect record { data: { first_name,
// emails: [...] } }. Put the verified status back on the original
// prospect (paired item through Switch), so a verified email is a
// lead instead of being dropped.
if (!$json.data || !Array.isArray($json.data) || !$json.data[0]) {
  return { json: {} }; // the empty item from "Always Output Data"
}
const prospect = JSON.parse(JSON.stringify($('Switch').item.json));
const verified = $json.data[0];
if (prospect.data && Array.isArray(prospect.data.emails) && prospect.data.emails[0]) {
  prospect.data.emails[0].smtp_status = (verified.result && verified.result.smtp_status) || 'valid';
}
return { json: prospect };

// Only contacts with a verified email go on. If there is none, say
// so: the backend shows the user "no valid emails found" and charges
// nothing.
const withEmail = $input.all().filter(i => {
  const d = i.json && i.json.data;
  const e = d && !Array.isArray(d) && Array.isArray(d.emails) ? d.emails[0] : null;
  return e && e.email && e.smtp_status === 'valid';
});
if (!withEmail.length) {
  throw new Error(`LeadPilot Error: no_valid_emails_found - none of the ${$input.all().length} decision makers had a verifiable email address.`);
}
return withEmail;

// Robustly import parsePhoneNumberFromString across different package versions
const libPhone = require('libphonenumber-js');
const parseFn = libPhone.parsePhoneNumberFromString || libPhone.default?.parsePhoneNumberFromString;

// 1. Build a dictionary of company countries and HQ phones from domain search results
const domainNodes = $('Get domain search result').all();
const hqPhoneMap = {};

for (const d of domainNodes) {
  const data = d.json.data || d.json || {};
  const site = (data.website || data.domain || d.json.domain || (d.json.meta && d.json.meta.domain) || '')
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .toLowerCase();

  if (site) {
    hqPhoneMap[site] = {
      phone: data.hq_phone || data.company_phone || '',
      country: data.country_code || data.country || 'US' // Fallback to US
    };
  }
}

// 2. Parse raw numbers and add clean_phone to each item
for (const item of $input.all()) {
  const data = item.json.data || item.json;

  const email = data.emails?.[0]?.email || data.email || '';
  const domain = email.includes('@') ? email.split('@')[1].toLowerCase() : '';

  const companyInfo = hqPhoneMap[domain] || { phone: '', country: 'US' };
  let rawPhone = data.phone || data.phone_number || companyInfo.phone || '';

  if (rawPhone && typeof parseFn === 'function') {
    const parsed = parseFn(String(rawPhone), companyInfo.country);

    if (parsed && parsed.isValid()) {
      item.json.clean_phone = parsed.number.replace('+', ''); // e.g., 18002223142
    } else {
      let digits = String(rawPhone).replace(/[^0-9]/g, '');
      if (digits.length === 10) digits = '1' + digits;
      item.json.clean_phone = digits;
    }
  } else if (rawPhone) {
    // Fallback if parser fails to load
    let digits = String(rawPhone).replace(/[^0-9]/g, '');
    if (digits.length === 10) digits = '1' + digits;
    item.json.clean_phone = digits;
  } else {
    item.json.clean_phone = null;
  }
}

return $input.all();

// Unique phone numbers for the WhatsApp check. Never returns nothing:
// with no phone at all it emits a marker, so the run still reaches
// Group Leads (which reads its contacts from Merge, not from here).
const seen = new Set();
const phones = [];
for (const item of $input.all()) {
  const phone = item.json.clean_phone;
  if (!phone || seen.has(phone)) continue;
  seen.add(phone);
  phones.push(item);
}
return phones.length ? phones : [{ json: { _no_phones: true } }];

const companyMap = {};

// 0. Check if WhatsApp validation was requested from backend Webhook
const webhookData = $('Webhook').first().json;
const body = webhookData.body || webhookData;
const isWhatsappValidationEnabled = body.validate_whatsapp === true;

// Helper to extract last 10 digits for phone lookup
function getPhoneKey(phone) {
  if (!phone) return '';
  const digits = String(phone).replace(/[^0-9]/g, '');
  return digits.length >= 10 ? digits.slice(-10) : digits;
}

// 1. Build Company Profile Lookup Map from "Get domain search result"
const companyDetailsMap = {};
try {
  const domainNodes = $('Get domain search result').all();
  for (const domItem of domainNodes) {
    const cData = domItem.json.data || domItem.json || {};
    const site = cData.website || domItem.json.website || cData.domain || domItem.json.domain || (domItem.json.meta && domItem.json.meta.domain) || '';
    const domKey = site.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase();

    if (domKey) {
      companyDetailsMap[domKey] = {
        company_name: cData.company_name || cData.name || domItem.json.company_name || "",
        company_size: cData.size || cData.company_size || domItem.json.size || domItem.json.company_size || "N/A",
        industry: cData.industry || domItem.json.industry || "N/A",
        hq_phone: cData.hq_phone || cData.company_phone || domItem.json.hq_phone || domItem.json.company_phone || ""
      };
    }
  }
} catch (e) {
  // Fallback if node was skipped
}

// 2. Fetch raw profiles for job title fallback lookup
const positionLookupMap = {};
try {
  const rawProfiles = $('Get prospect profiles result').all();
  for (const profileItem of rawProfiles) {
    const dataList = profileItem.json.data || [];
    for (const person of dataList) {
      const fn = (person.first_name || '').trim().toLowerCase();
      const ln = (person.last_name || '').trim().toLowerCase();
      const key = `${fn}_${ln}`;
      if (person.position) {
        positionLookupMap[key] = person.position;
      }
    }
  }
} catch (e) {}

// 3. Fetch WhatsApp validation status map (if enabled)
const whatsappMap = {};
if (isWhatsappValidationEnabled) {
  try {
    const whatsappResults = $('WhatsApp Validator').all();
    for (const wa of whatsappResults) {
      const rawPhone = wa.json.clean_phone || wa.json.phone_number || wa.json.phone || '';
      const key = getPhoneKey(rawPhone);
      if (key) {
        const statusVal = wa.json.status || wa.json.whatsapp_status || "";
        const isExists = wa.json.exists === true || statusVal.toLowerCase() === "valid" || statusVal.toLowerCase() === "exists" || statusVal.toLowerCase() === "active";
        whatsappMap[key] = isExists ? "Active" : "Not Active";
      }
    }
  } catch (e) {}
}

// 4. Process and group prospects from Merge node
const enrichedProspects = $('Merge').all();

for (const item of enrichedProspects) {
  const data = item.json.data || item.json || {};

  // Extract email & domain
  const email = data.emails?.[0]?.email || data.email || item.json.email || '';
  const domain = email.includes('@')
    ? email.split('@')[1].toLowerCase()
    : (item.json.website || '').replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase();

  if (!domain) continue;

  // Retrieve original company metadata from domain search lookup map
  const details = companyDetailsMap[domain] || {};

  // Initialize company entry with true company metadata
  if (!companyMap[domain]) {
    companyMap[domain] = {
      domain: domain,
      company_name: details.company_name || item.json.company_name || data.company_name || "",
      website: domain,
      company_size: details.company_size || item.json.company_size || item.json.employees || data.company_size || "N/A",
      industry: details.industry || item.json.industry || data.industry || "N/A",
      hq_phone: details.hq_phone || item.json.company_phone || data.company_phone || "",
      decision_makers: []
    };
  }

  // Extract decision-maker name & position
  const firstName = data.first_name || item.json.first_name || '';
  const lastName = data.last_name || item.json.last_name || '';
  const fullName = `${firstName} ${lastName}`.trim() || 'Decision Maker';
  const personKey = `${firstName.trim().toLowerCase()}_${lastName.trim().toLowerCase()}`;

  const extractedPosition =
    data.position || item.json.position || data.job_title || item.json.job_title || positionLookupMap[personKey] || "N/A";

  // Determine prospect phone number
  let prospectPhone = item.json.clean_phone || item.json.phone_number || data.phone || null;
  if (!prospectPhone && Array.isArray(data.phone_numbers) && data.phone_numbers.length > 0) {
    prospectPhone = data.phone_numbers[0].phone || null;
  }
  if (!prospectPhone) {
    prospectPhone = companyMap[domain].hq_phone || null;
  }

  const phoneKey = getPhoneKey(prospectPhone);

  // Toggle WhatsApp Status
  let whatsappStatus = null;
  if (isWhatsappValidationEnabled) {
    if (prospectPhone) {
      whatsappStatus = (phoneKey && whatsappMap[phoneKey] !== undefined) ? whatsappMap[phoneKey] : "Not Checked";
    } else {
      whatsappStatus = null;
    }
  }

  // Append decision maker
  companyMap[domain].decision_makers.push({
    full_name: fullName,
    job_title: extractedPosition,
    verified_email: email || null,
    email_status: data.emails?.[0]?.smtp_status || item.json.smtp_status || "valid",
    linkedin_url: item.json.linkedin_url || data.linkedin_url || item.json.source_page || data.source_page || null,
    phone_number: prospectPhone || null,
    whatsapp_status: whatsappStatus
  });
}

// Abandon Rule: Silently discard companies with 0 valid decision makers
const qualifiedCompanies = Object.values(companyMap).filter(company => company.decision_makers.length > 0);

if (!qualifiedCompanies.length) {
  throw new Error('LeadPilot Error: no_valid_emails_found - no company was left with a verified decision maker.');
}
return qualifiedCompanies.map(company => ({ json: { ...company } }));
